{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT attr_k8s_deployment_name dep, metric, round(avg(value),2) avg_v, count(*) n FROM abnormal_metrics WHERE metric IN ('k8s.deployment.available','k8s.deployment.desired') AND attr_k8s_deployment_name='profile' GROUP BY ALL", "claim": "Profile deployment has 0 available replicas against 1 desired for the whole incident window."},
        {"kind": "metric", "sql": "SELECT service_name, attr_k8s_pod_name pod, count(*) n FROM normal_metrics WHERE service_name='profile' AND metric='container.cpu.usage' GROUP BY ALL UNION ALL SELECT service_name, attr_k8s_pod_name, count(*) FROM abnormal_metrics WHERE service_name='profile' AND metric='container.cpu.usage' GROUP BY ALL", "claim": "The profile pod reports metrics in the normal period but has no metrics at all in the abnormal period."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n FROM normal_traces WHERE service_name='profile' GROUP BY ALL UNION ALL SELECT service_name, span_name, attr_span_kind, count(*) FROM abnormal_traces WHERE service_name='profile' GROUP BY ALL", "claim": "Profile emits 1731 server spans in the normal period and none in the abnormal period."},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles' GROUP BY ALL", "claim": "Every frontend call to profile.GetProfiles errors out within about 0.01 ms, 677 of 677 calls."}
      ]
    },
    {
      "service": "search",
      "fault_kind": "dns_lookup_failed",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(quantile_cont(duration,0.5)/1e6,3) p50_ms, round(max(duration)/1e6,3) max_ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY ALL", "claim": "All 938 search calls to rate.Rate/GetRates fail, each in about 0.01 ms, before any connection is established."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' OR (service_name='rate') GROUP BY ALL UNION ALL SELECT service_name, span_name, attr_span_kind, count(*) FROM normal_traces WHERE span_name='rate.Rate/GetRates' OR service_name='rate' GROUP BY ALL", "claim": "The rate service records no spans in the abnormal period, though it recorded 855 server spans normally."},
        {"kind": "metric", "sql": "SELECT attr_k8s_deployment_name dep, metric, round(avg(value),2) avg_v, count(*) n FROM abnormal_metrics WHERE attr_k8s_deployment_name='rate' AND metric IN ('k8s.deployment.available','k8s.deployment.desired','container.cpu.usage','container.memory.usage') GROUP BY ALL", "claim": "The rate deployment stays fully available with idle CPU and flat memory, so rate itself is not saturated or down."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='search' AND level='ERROR' GROUP BY ALL", "claim": "Search logs 1442 errors 'Failed to get rates from rate service' during the incident."}
      ]
    }
  ],
  "propagation": [
    {"from": "profile", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name='HTTP /recommendations' GROUP BY ALL", "claim": "Frontend /recommendations requests fail with 500 in 677 of 677 cases, matching the failed profile calls."}]},
    {"from": "search", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_http_response_status_code code, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name='HTTP /hotels' GROUP BY ALL", "claim": "Frontend /hotels requests return 500 in 1118 of 1118 cases, because the search.Search/Nearby calls fail."}]},
    {"from": "rate", "to": "search",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='search' AND attr_span_kind='Server' GROUP BY ALL", "claim": "Every search.Search/Nearby server span errors (938 of 938) after its rate lookup fails."}]}
  ]
}
